export const SANDBOX_BOOTSTRAP_SOURCE="/* First-party bootstrap loaded in an opaque-origin sandbox. Not plugin-supplied code. */\n(() => {\n  'use strict';\n  const channel='nvideo-sandbox-v1';\n  const root=document.getElementById('plugin-root');\n  const send=(type,message)=>window.parent.postMessage({\n    channel,type,message:String(message||'').slice(0,240)\n  },'*');\n  let started=false;\n  window.addEventListener('message',async event=>{\n    if(event.source!==window.parent||event.data?.channel!==channel||\n       event.data.type!=='init'||started)return;\n    started=true;\n    const code=event.data.code;\n    if(typeof code!=='string'||!code.trim()||code.length>16*1024){\n      send('error','Invalid sandbox module');return;\n    }\n    let url;\n    try{\n      // A sandboxed iframe has opaque origin; no Tauri bootstrap or shared DOM.\n      const blob=new Blob([code],{type:'text/javascript'});\n      url=URL.createObjectURL(blob);\n      const mod=await import(url);\n      if(typeof mod.default!=='function')throw Error('export default function(api) is required');\n      let serial=0;\n      const pending=new Map();\n      const hostInfo=()=>new Promise((resolve,reject)=>{\n        const requestId=String(++serial);\n        const timeout=setTimeout(()=>{\n          pending.delete(requestId);\n          reject(Error('Host request timeout'));\n        },8000);\n        pending.set(requestId,{resolve,reject,timeout});\n        window.parent.postMessage({channel,type:'host-request',method:'host:info',requestId},'*');\n      });\n      window.addEventListener('message',event=>{\n        if(event.source!==window.parent||event.data?.channel!==channel||\n           event.data.type!=='host-response'||typeof event.data.requestId!=='string')return;\n        const request=pending.get(event.data.requestId);\n        if(!request)return;\n        pending.delete(event.data.requestId);\n        clearTimeout(request.timeout);\n        if(typeof event.data.error==='string')request.reject(Error(event.data.error.slice(0,160)));\n        else if(event.data.result&&typeof event.data.result.appName==='string'&&\n           typeof event.data.result.apiVersion==='string')request.resolve(event.data.result);\n        else request.reject(Error('Invalid host response'));\n      });\n      const api=Object.freeze({root,log:message=>send('log',message),hostInfo});\n      await mod.default(api);\n      send('started','Sandbox module started');\n    }catch(error){\n      root.replaceChildren();\n      const message=document.createElement('p');\n      message.textContent='Plugin launch failed: '+String(error).slice(0,160);\n      root.append(message);\n      send('error',String(error));\n    }finally{if(url)URL.revokeObjectURL(url)}\n  });\n  send('ready','Sandbox ready');\n})();\n";
